"""Signal-only linear stages with local device references and common stream waves."""
from .model_file import _object, analyze


def _linear_stage_samples(library, network, frequencies, reference, base_directory=None):
    _object(network, ("devices", "external_ports"), ("connections", "terminations"))
    devices = network["devices"]
    if not isinstance(devices, list) or not devices:
        raise ValueError("At least one linear stage device is required")
    for device in devices:
        # Stage frequencies are generated by upstream nonlinear/mixer operations.
        # Positional per-frequency arrays are intentionally not part of this format.
        _object(device, ("id",), ("s", "model", "reference_impedances_ohms"))
    document = dict(network, format="rfmodel.linear-network", version=1,
                    frequencies_hz=frequencies, reference_ohms=reference)
    if any("reference_impedances_ohms" in device for device in devices):
        external = network["external_ports"]
        if not isinstance(external, list) or not 1 <= len(external) <= 1024:
            raise ValueError("Select 1..1024 external ports")
        # A local S matrix cannot be interpreted as a common-reference stage S.
        # The native power-wave transform also changes external source/load match.
        document["output_reference_impedances_ohms"] = [reference] * len(external)
    return analyze(library, document, base_directory=base_directory)["samples"]
